@security.private
def _getSnapshotFolder(self, subdir=None):
    """ Return the appropriate snapshot (sub)folder.
    """
    path = ['snapshots', self._snapshot_id]

    if subdir is not None:
        path.extend(subdir.split('/'))

    return self._tool.restrictedTraverse(path)
